-- Operon product range pricing seed.
-- One editable Supabase row per catalogue range.
-- Generated from apps/web-tsx/public/products.js.
-- Price columns are intentionally not overwritten on conflict.

create table if not exists public.operon_product_ranges (
  id text primary key,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  category_id text not null,
  brand text not null default '',
  range_name text not null,
  selection_mode text not null default '',
  thickness text,
  product_type text,
  representative_product_id text,
  representative_image_url text,
  alt_text text,
  supplier text,
  supplier_url text,
  colour_count integer not null default 0,
  colours jsonb not null default '[]'::jsonb,
  technical_summary jsonb not null default '[]'::jsonb,
  source_product_count integer not null default 0,
  price_per_m2 numeric,
  install_rate_override numeric,
  price_notes text,
  pricing_status text not null default 'pending',
  active boolean not null default true,
  sort_order integer not null default 100
);

comment on table public.operon_product_ranges is 'Range-level product pricing admin table. One row represents one catalogue range; colour-level exceptions can be added later if needed.';
comment on column public.operon_product_ranges.price_per_m2 is 'Editable range-level material price. Null/pending until manually set.';
comment on column public.operon_product_ranges.install_rate_override is 'Optional install override for this range only. Leave null for category/default install logic.';

create index if not exists operon_product_ranges_category_idx on public.operon_product_ranges(category_id, active, sort_order);
create index if not exists operon_product_ranges_pricing_status_idx on public.operon_product_ranges(pricing_status, category_id);

create or replace function public.operon_product_ranges_set_updated_at()
returns trigger as $$
begin
  new.updated_at = now();
  return new;
end;
$$ language plpgsql;

drop trigger if exists set_operon_product_ranges_updated_at on public.operon_product_ranges;
create trigger set_operon_product_ranges_updated_at
before update on public.operon_product_ranges
for each row execute function public.operon_product_ranges_set_updated_at();

alter table public.operon_product_ranges enable row level security;
revoke all on table public.operon_product_ranges from anon;
revoke all on table public.operon_product_ranges from authenticated;

