on conflict (id) do update set
  category_id = excluded.category_id,
  brand = excluded.brand,
  range_name = excluded.range_name,
  selection_mode = excluded.selection_mode,
  thickness = excluded.thickness,
  product_type = excluded.product_type,
  representative_product_id = excluded.representative_product_id,
  representative_image_url = excluded.representative_image_url,
  alt_text = excluded.alt_text,
  supplier = excluded.supplier,
  supplier_url = excluded.supplier_url,
  colour_count = excluded.colour_count,
  colours = excluded.colours,
  technical_summary = excluded.technical_summary,
  source_product_count = excluded.source_product_count,
  active = excluded.active,
  sort_order = excluded.sort_order;

select category_id, count(*) as range_count
from public.operon_product_ranges
group by category_id
order by category_id;
